<template>
  <div v-if="allowed" class="page">
    <!-- 顶部标题 -->
    <header class="header">
      <h1 class="title">OFotos</h1>
    </header>

    <!-- 初始加载 -->
    <div v-if="initialLoading" class="initial-loading">
      <van-loading color="#fff" size="24">加载中...</van-loading>
    </div>

    <!-- 相册内容 -->
    <div v-else class="gallery">
      <!-- 按日期分组 -->
      <template v-if="!flatMode">
        <section
          v-for="group in groupedItems"
          :key="group.date"
          class="date-group fade-in"
        >
          <div class="date-title">{{ group.date }}</div>
          <div class="grid" :style="gridStyle">
            <div
              v-for="item in group.items"
              :key="item.id"
              class="grid-item"
              @click="openPreview(item)"
            >
              <img
                :src="item.url"
                :alt="item.authorId"
                loading="lazy"
                :class="{ 'img-loaded': item.loaded }"
                @load="onImgLoad(item, $event)"
                @error="markLoaded(item)"
              />
              <a-skeleton v-if="!item.loaded" animation class="grid-skeleton">
                <a-skeleton-shape shape="square" />
              </a-skeleton>
            </div>
          </div>
        </section>
      </template>

      <!-- 平铺模式 -->
      <div v-else class="grid fade-in" :style="gridStyle">
        <div
          v-for="item in pagedItems"
          :key="item.id"
          class="grid-item"
          @click="openPreview(item)"
        >
          <img
            :src="item.url"
            :alt="item.authorId"
            loading="lazy"
            :class="{ 'img-loaded': item.loaded }"
            @load="onImgLoad(item, $event)"
            @error="markLoaded(item)"
          />
          <a-skeleton v-if="!item.loaded" animation class="grid-skeleton">
            <a-skeleton-shape shape="square" />
          </a-skeleton>
        </div>
      </div>

      <!-- 空状态 -->
      <div v-if="!items.length" class="empty">暂无图片</div>

      <!-- 触底加载哨兵 -->
      <div ref="sentinel" class="sentinel"></div>
      <div class="load-status" v-if="loadingMore" >
        <van-loading color="#fff" size="18" />
      </div>
    </div>

    <!-- 底部悬浮按钮区 -->
    <div ref="floatBar" class="float-bar">
      <template v-if="!previewItem">
        <button
          class="round-btn round-btn-right"
          key="btn-1"
          :title="flatMode ? '按日期分组' : '平铺'"
          @click="toggleMode"
        >
          <van-icon :name="flatMode ? 'notes-o' : 'list-switching'" />
        </button>
        <button class="round-btn round-btn--primary round-btn-left" key="btn-2" title="新增图片" @click="openUpload">
          <van-icon name="plus" />
        </button>
      </template>
      <template v-else>
        <button class="round-btn round-btn-right" key="btn-3" title="保存" @click="downloadImage(previewItem)">
          <van-icon name="back-top" style="transform: rotate(180deg);"/>
        </button>
        <button
          class="round-btn round-btn-middle"
          key="btn-share"
          :title="isMobile ? '转发' : '复制'"
          @click="shareOrCopy(previewItem)"
        >
          <van-icon name="share-o" />
        </button>
        <button
          :class="!hasValidPreview?'btn-disable':''"
          class="round-btn round-btn--primary round-btn-left"
          key="btn-4"
          title="跳转"
          @click="jumpToAuthor(previewItem)"
        >
          <van-icon name="link-o" />
          <img v-if="previewItem.platform" :src="platformIcon(previewItem.platform)" class="preview-platform-icon" alt="" />
        </button>
      </template>
    </div>

    <!-- 大图预览 -->
    <transition name="fade">
      <div v-if="previewItem" class="preview-layer">
        <div class="preview-header">
          <span class="preview-date-day">{{ formatDate(previewItem.createdAt, 1) }}</span>
          <span class="preview-date-time">{{ formatDate(previewItem.createdAt, 2) }}</span>
        </div>
        <div
          class="preview-swipe"
          @touchstart="onTouchStart"
          @touchmove.prevent="onTouchMove"
          @touchend="onTouchEnd"
          @touchcancel="onTouchEnd"
        >
          <div class="swipe-track" :class="{ dragging, 'no-anim': justJumped }" :style="swipeStyle">
            <div class="swipe-img-wrap" @click="closePreview">
              <img v-if="prevPreview" :src="prevPreview.url" class="preview-img" alt="" />
            </div>
            <div class="swipe-img-wrap" @click="closePreview">
              <img
                :src="previewItem.url"
                :key="previewItem.id"
                class="preview-img preview-img-current"
                :class="{ 'preview-img-ready': previewImgReady }"
                @load="onPreviewImgLoad"
                alt=""
              />
            </div>
            <div class="swipe-img-wrap" @click="closePreview">
              <img v-if="nextPreview" :src="nextPreview.url" class="preview-img" alt="" />
            </div>
          </div>
        </div>
      </div>
    </transition>

    <!-- 新增图片弹窗 -->
    <a-modal
      v-model:visible="showUpload"
      title="新增图片"
      :footer="false"
      :width="modalWidth"
      :unmount-on-close="true"
      :modal-style="{ borderRadius: '12px' }"
    >
      <div class="upload-body">
        <div class="seg">
          <div
            class="seg-item"
            :class="{ active: uploadType === 'local' }"
            @click="uploadType = 'local'"
          >
            <icon-image />
            <span>本地图片</span>
          </div>
          <div
            class="seg-item"
            :class="{ active: uploadType === 'url' }"
            @click="uploadType = 'url'"
          >
            <icon-link />
            <span>URL 地址</span>
          </div>
        </div>

        <div v-if="uploadType === 'local'" class="seg-panel">
          <a-upload
            v-model:file-list="uploadFileList"
            :auto-upload="false"
            :show-file-list="false"
            accept="image/*"
            @change="onFileChange"
          >
            <template #upload-button>
              <div v-if="!previewSrc" class="upload-trigger">
                <icon-plus />
                <span>选择图片</span>
              </div>
              <div v-else class="upload-preview">
                <img :src="previewSrc" alt="" />
              </div>
            </template>
          </a-upload>
        </div>
        <div v-else>
          <div class="field-item">
            <span class="field-label">URL</span>
            <a-input v-model="urlInput" placeholder="图片地址" class="field-control" />
          </div>
        </div>

        <!-- 平台下拉 -->
        <div class="field-item">
          <span class="field-label">平台</span>
          <a-select v-model="platform" placeholder="选择平台" class="field-control">
            <a-option
              v-for="opt in PLATFORM_OPTIONS"
              :key="opt.value"
              :value="opt.value"
              :label="opt.text"
            >
              <div class="platform-option">
                <img :src="opt.icon" class="platform-icon" alt="" />
                <span>{{ opt.text }}</span>
              </div>
            </a-option>
          </a-select>
        </div>

        <!-- 博主ID -->
        <div class="field-item">
          <span class="field-label">博主</span>
          <a-input v-model="authorId" placeholder="输入博主ID" class="field-control" />
        </div>

        <a-button type="primary" long :loading="submitting" class="submit-btn" @click="submit">
          确认上传
        </a-button>
      </div>
    </a-modal>
  </div>
</template>

<script>
import Message from '@arco-design/web-vue/es/message'
import { uploadImage, uploadJson, fetchList, getDownloadUrl } from './utils/cloudinary'
import { PLATFORMS, PLATFORM_OPTIONS } from './config/platforms'

const ACCESS_KEY = 't'
const ACCESS_VALUE = '1'

// 校验入参：必须携带 t=1，否则不渲染任何内容
function checkAccess() {
  const search = window.location.search || ''
  const hashQuery = window.location.hash && window.location.hash.indexOf('?') > -1
    ? window.location.hash.slice(window.location.hash.indexOf('?') + 1)
    : ''
  const params = new URLSearchParams(search || hashQuery)
  return params.get(ACCESS_KEY) === ACCESS_VALUE
}

export default {
  name: 'App',
  data() {
    return {
      allowed: checkAccess(),
      items: [],
      initialLoading: true,
      loadingMore: false,
      finished: false,
      visibleCount: 30,
      pageSize: 30,
      flatMode: false,
      showUpload: false,
      uploadType: 'local',
      pendingFile: null,
      uploadFileList: [],
      urlInput: '',
      platform: '',
      authorId: '',
      submitting: false,
      previewItem: null,
      previewIndex: 0,
      previewImgReady: false,
      dragX: 0,
      dragging: false,
      justJumped: false,
      swipeTimer: null,
      touchStartX: 0,
      touchStartY: 0,
      localPreviewUrl: '',
      cols: 3,
      PLATFORM_OPTIONS,
      observer: null,
      resizeTimer: null,
      dragRaf: null,
      pendingDragX: 0,
      currentYear: new Date().getFullYear()
    }
  },
  computed: {
    modalWidth() {
      return Math.min(window.innerWidth * 0.9, 500)
    },
    sortedItems() {
      return [...this.items].sort((a, b) => b._ts - a._ts)
    },
    pagedItems() {
      return this.sortedItems.slice(0, this.visibleCount)
    },
    indexById() {
      const map = new Map()
      this.pagedItems.forEach((item, i) => map.set(item.id, i))
      return map
    },
    groupedItems() {
      const groups = []
      const map = {}
      for (const item of this.pagedItems) {
        const date = item._day || ''
        if (!map[date]) {
          map[date] = { date, items: [] }
          groups.push(map[date])
        }
        map[date].items.push(item)
      }
      return groups
    },
    gridStyle() {
      return { gridTemplateColumns: `repeat(${this.cols}, 1fr)` }
    },
    previewSrc() {
      if (this.uploadType === 'local') {
        return this.localPreviewUrl
      }
      return this.urlInput.trim()
    },
    prevPreview() {
      return this.previewIndex > 0 ? this.pagedItems[this.previewIndex - 1] : null
    },
    nextPreview() {
      return this.previewIndex < this.pagedItems.length - 1
        ? this.pagedItems[this.previewIndex + 1]
        : null
    },
    swipeStyle() {
      return { transform: `translateX(calc(-100% + ${this.dragX}px))` }
    },
    hasValidPreview() {
      const item = this.previewItem
      return !!(item && item.url && item.platform && PLATFORMS[item.platform])
    },
    isMobile() {
      const ua = navigator.userAgent
      return /Android|iPhone|iPad|iPod|Mobile|Windows Phone/i.test(ua) ||
        (/Macintosh/i.test(ua) && navigator.maxTouchPoints > 1)
    }
  },
  async mounted() {
    if (!this.allowed) return
    this.calcLayout()
    await this.loadData()
    window.addEventListener('resize', this.onResize)
    this.$nextTick(() => this.animateFloatWidth(false))
  },
  watch: {
    previewItem() {
      this.$nextTick(() => this.animateFloatWidth(true))
    }
  },
  beforeUnmount() {
    if (this.observer) this.observer.disconnect()
    window.removeEventListener('resize', this.onResize)
    clearTimeout(this.resizeTimer)
    if (this.dragRaf) cancelAnimationFrame(this.dragRaf)
    if (this.localPreviewUrl) URL.revokeObjectURL(this.localPreviewUrl)
    clearTimeout(this.swipeTimer)
  },
  methods: {
    async loadData() {
      this.initialLoading = true
      try {
        const data = await fetchList()
        const raw = data && Array.isArray(data.items) ? data.items : []
        this.items = raw.map((item) => this.decorateItem(item))
      } catch (e) {
        this.items = []
        Message.error(e.message || '加载数据失败')
      } finally {
        this.initialLoading = false
        this.visibleCount = this.pageSize
        this.finished = this.items.length <= this.pageSize
        this.$nextTick(() => this.setupObserver())
      }
    },
    setupObserver() {
      if (!window.IntersectionObserver) {
        this.finished = true
        return
      }
      const el = this.$refs.sentinel
      if (!el) return
      if (this.observer) this.observer.disconnect()
      let first = true
      this.observer = new IntersectionObserver(
        (entries) => {
          // 忽略 observe 后的首次回调（初始状态），避免进入页面就自动触发加载
          if (first) {
            first = false
            return
          }
          if (entries[0].isIntersecting) this.loadMore()
        },
        { rootMargin: '100px 0px' }
      )
      this.observer.observe(el)
    },
    loadMore() {
      if (this.loadingMore || this.finished || this.initialLoading) return
      this.loadingMore = true
      setTimeout(() => {
        this.visibleCount += this.pageSize
        if (this.visibleCount >= this.items.length) {
          this.visibleCount = this.items.length
          this.finished = true
        }
        this.loadingMore = false
      }, 250)
    },
    toggleMode() {
      this.flatMode = !this.flatMode
    },
    openUpload() {
      this.uploadType = 'local'
      this.pendingFile = null
      this.uploadFileList = []
      this.urlInput = ''
      this.platform = ''
      this.authorId = ''
      if (this.localPreviewUrl) {
        URL.revokeObjectURL(this.localPreviewUrl)
        this.localPreviewUrl = ''
      }
      this.showUpload = true
    },
    onFileChange(fileList, fileItem) {
      this.pendingFile = (fileItem && fileItem.file) || null
      if (this.localPreviewUrl) {
        URL.revokeObjectURL(this.localPreviewUrl)
        this.localPreviewUrl = ''
      }
      if (this.pendingFile) {
        this.localPreviewUrl = URL.createObjectURL(this.pendingFile)
        this.uploadFileList = [fileItem]
      }
    },
    async submit() {
      const isLocal = this.uploadType === 'local'
      const source = isLocal ? this.pendingFile : this.urlInput.trim()
      if (!source) {
        Message.warning('请先选择或填写图片')
        return
      }

      this.submitting = true
      try {
        const { url } = await uploadImage(source)
        const newItem = this.decorateItem({
          id: Date.now().toString(36) + Math.random().toString(36).slice(2, 8),
          url,
          platform: this.platform,
          authorId: this.authorId.trim(),
          createdAt: new Date().toISOString()
        })
        const nextItems = [...this.items, newItem]
        await uploadJson({
          version: 1,
          updatedAt: new Date().toISOString(),
          items: nextItems.map((item) => this.toPlainItem(item))
        })

        this.items = nextItems
        this.visibleCount = this.pageSize
        this.finished = this.items.length <= this.pageSize
        this.showUpload = false
        if (this.localPreviewUrl) {
          URL.revokeObjectURL(this.localPreviewUrl)
          this.localPreviewUrl = ''
        }
        this.pendingFile = null
        this.uploadFileList = []
        // Message.success('上传成功')
      } catch (e) {
        Message.error(e.message || '上传失败')
      } finally {
        this.submitting = false
      }
    },
    openPreview(item) {
      this.previewItem = item
      const idx = this.indexById.get(item.id)
      this.previewIndex = idx == null ? 0 : idx
      this.dragX = 0
      this.dragging = false
      this.justJumped = false
      this.previewImgReady = false
      clearTimeout(this.swipeTimer)
    },
    closePreview() {
      this.previewItem = null
      this.dragX = 0
      this.dragging = false
    },
    async onPreviewImgLoad(e) {
      const img = e.target
      if (img && img.decode) {
        try {
          await img.decode()
        } catch (err) {
          // 解码失败也继续显示
        }
      }
      this.previewImgReady = true
    },
    onTouchStart(e) {
      this.touchStartX = e.touches[0].clientX
      this.touchStartY = e.touches[0].clientY
      this.dragging = true
      this.dragX = 0
    },
    onTouchMove(e) {
      if (!this.dragging) return
      const dx = e.touches[0].clientX - this.touchStartX
      const dy = e.touches[0].clientY - this.touchStartY
      if (Math.abs(dx) <= Math.abs(dy)) return
      this.pendingDragX = dx
      if (this.dragRaf) return
      this.dragRaf = requestAnimationFrame(() => {
        this.dragRaf = null
        this.dragX = this.pendingDragX
      })
    },
    onTouchEnd() {
      if (!this.dragging) return
      this.dragging = false
      if (this.dragRaf) {
        cancelAnimationFrame(this.dragRaf)
        this.dragRaf = null
        this.dragX = this.pendingDragX
      }
      const threshold = 60
      const w = window.innerWidth
      if (this.dragX < -threshold && this.nextPreview) {
        this.dragX = -w
        this.finishSwipe('next')
      } else if (this.dragX > threshold && this.prevPreview) {
        this.dragX = w
        this.finishSwipe('prev')
      } else {
        this.dragX = 0
      }
    },
    finishSwipe(dir) {
      clearTimeout(this.swipeTimer)

      const step = dir === 'next' ? 1 : -1
      const targetIndex = this.previewIndex + step
      const target = this.pagedItems[targetIndex]
      if (!target) {
        this.dragX = 0
        return
      }

      // 预解码目标图：prev/next 图已在 DOM 中预加载，命中缓存很快，
      // 避免切换后 previewImgReady 归零导致“暗一下再亮”。300ms 超时兜底。
      const decodePromise = target.url
        ? new Promise((resolve) => {
            const img = new Image()
            const done = () => resolve()
            img.onload = () => img.decode().then(done, done)
            img.onerror = done
            img.src = target.url
            setTimeout(done, 300)
          })
        : Promise.resolve()

      this.swipeTimer = setTimeout(async () => {
        await decodePromise

        this.previewIndex = targetIndex
        this.previewItem = target
        this.previewImgReady = true

        // 开启无动画模式，再复位轨道
        this.justJumped = true
        this.dragX = 0

        this.$nextTick(() => {
          // 确保浏览器先应用无动画样式
          requestAnimationFrame(() => {
            requestAnimationFrame(() => {
              this.justJumped = false
            })
          })
        })
      }, 250)
    },
    downloadImage(item) {
      const url = getDownloadUrl(item.url)
      const a = document.createElement('a')
      a.href = url
      a.target = '_blank'
      a.rel = 'noopener'
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
    },
    jumpToAuthor(item) {
      const p = PLATFORMS[item.platform]
      if (!p || !p.httpPre) {
        Message.warning('该平台暂无跳转配置')
        return
      }
      window.open(p.httpPre + item.authorId, '_blank')
    },
    formatDate(iso, type = 0) {
      const d = new Date(iso)

      if (isNaN(d.getTime())) return ''

      const y = d.getFullYear()
      const m = d.getMonth() + 1
      const day = d.getDate()
      const hours = String(d.getHours()).padStart(2, '0')
      const minutes = String(d.getMinutes()).padStart(2, '0')

      switch (type) {
        case 1:
          return `${y} 年 ${m} 月 ${day} 日`
        case 2:
          return `${hours}:${minutes}`
        default:
          if (y === this.currentYear) {
            return `${m} 月 ${day} 日`
          }
          return `${y} 年 ${m} 月 ${day} 日`
      }
    },
    decorateItem(item) {
      if (!item) return item
      const ts = new Date(item.createdAt).getTime()
      item._ts = Number.isNaN(ts) ? 0 : ts
      if (item._ts) {
        const d = new Date(item._ts)
        const y = d.getFullYear()
        const m = d.getMonth() + 1
        const day = d.getDate()
        item._day = y === this.currentYear
          ? `${m} 月 ${day} 日`
          : `${y} 年 ${m} 月 ${day} 日`
      } else {
        item._day = ''
      }
      item.loaded = false
      return item
    },
    toPlainItem(item) {
      return {
        id: item.id,
        url: item.url,
        platform: item.platform,
        authorId: item.authorId,
        createdAt: item.createdAt
      }
    },
    calcCols() {
      const pageWidth = this.$el ? this.$el.clientWidth : window.innerWidth
      const contentWidth = pageWidth - 28
      const cols = Math.max(2, Math.ceil(contentWidth / 120))
      this.cols = cols > 6 ? 6 : cols
    },
    calcPageSize() {
      const viewportH = window.innerHeight
      const contentW = (this.$el ? this.$el.clientWidth : window.innerWidth) - 28
      const cellSize = contentW / this.cols
      const rows = Math.ceil(viewportH / cellSize) - 1
      this.pageSize = Math.max(rows * this.cols, 6) + 1
    },
    calcLayout() {
      this.calcCols()
      this.calcPageSize()
    },
    onResize() {
      clearTimeout(this.resizeTimer)
      this.resizeTimer = setTimeout(() => this.calcLayout(), 150)
    },
    platformIcon(key) {
      return PLATFORMS[key] ? PLATFORMS[key].icon : ''
    },
    platformNameOf(key) {
      return PLATFORMS[key] ? PLATFORMS[key].name : ''
    },
    shareOrCopy(item) {
      if (this.isMobile) {
        this.shareImage(item)
      } else {
        this.copyImage(item)
      }
    },
    async shareImage(item) {
      if (!navigator.share) {
        this.copyImage(item)
        return
      }
      try {
        const blob = await fetch(item.url).then((r) => r.blob())
        const file = new File([blob], 'image.jpg', { type: blob.type || 'image/jpeg' })
        if (navigator.canShare && navigator.canShare({ files: [file] })) {
          await navigator.share({ files: [file], title: '分享图片' })
        } else {
          await navigator.share({ url: item.url, title: '分享图片' })
        }
      } catch (e) {
        if (e && e.name !== 'AbortError') {
          Message.error('分享失败')
        }
      }
    },
    async copyImage(item) {
      try {
        const blob = await fetch(item.url).then((r) => r.blob())
        if (navigator.clipboard && window.ClipboardItem) {
          await navigator.clipboard.write([
            new ClipboardItem({ [blob.type || 'image/png']: blob })
          ])
          Message.success('已复制图片')
        } else {
          await navigator.clipboard.writeText(item.url)
          Message.success('已复制链接')
        }
      } catch (e) {
        try {
          window.open(item.url, '_blank')
        } catch (e2) {
          Message.error('复制失败')
        }
      }
    },
    animateFloatWidth(animate = true) {
      const el = this.$refs.floatBar
      if (!el) return
      if (!animate) {
        el.style.width = el.getBoundingClientRect().width + 'px'
        return
      }
      const oldW = el.getBoundingClientRect().width
      el.style.width = 'auto'
      const newW = el.getBoundingClientRect().width
      el.style.width = oldW + 'px'
      void el.offsetWidth
      el.style.width = newW + 'px'
    },
    async onImgLoad(item, e) {
      const img = e.target
      if (img && img.decode) {
        try {
          await img.decode()
        } catch (err) {
          // 解码失败也继续显示
        }
      }
      this.markLoaded(item)
    },
    markLoaded(item) {
      item.loaded = true
    }
  }
}
